class Foo {
    mutex m1, m2;
public:
    Foo() {
        m1.lock();
        m2.lock();
    }

    void first(function<void()> printFirst) {
        printFirst();
        m1.unlock();
    }

    void second(function<void()> printSecond) {
        lock_guard<mutex> lk(m1);
        printSecond();
        m2.unlock();
    }

    void third(function<void()> printThird) {
        lock_guard<mutex> lk(m2);
        printThird();
    }
};
